1	import { matchMaker } from "colyseus";
2	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
3	import { seaMap } from "@pirate-sea-race/content";
4	import { MessageType, PROTOCOL_VERSION } from "@pirate-sea-race/protocol";
5	import { MatchRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
6	import { HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
7	
8	let server: RunningGameServer;
9	let endpoint: string;
10	const clients: HeadlessClient[] = [];
11	const MAP_CENTRE_X = (seaMap.widthTiles * seaMap.subUnitsPerTile) / 2;
12	
13	async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
14	  const joined = await client;
15	  clients.push(joined);
16	  return joined;
17	}
18	
19	beforeAll(async () => {
20	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false });
21	  endpoint = `http://127.0.0.1:${server.port}`;
22	});
23	
24	afterEach(async () => {
25	  await Promise.all(clients.splice(0).map((client) => client.leave()));
26	});
27	
28	afterAll(async () => {
29	  await server.close();
30	});
31	
32	function roomOf(client: HeadlessClient): MatchRoom {
33	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
34	}
35	
36	describe("private match", () => {
37	  it("creates a custom match with a six-character code", async () => {
38	    const host = await track(HeadlessClient.create(endpoint));
39	    expect(host.code).toMatch(/^[A-Z0-9]{6}$/);
40	    expect(host.room.state.custom).toBe(true);
41	    expect(host.room.state.protocolVersion).toBe(PROTOCOL_VERSION);
42	    expect(host.playerCount).toBe(1);
43	  });
44	
45	  it("lets two clients join the same code and see the same authoritative movement", async () => {
46	    const host = await track(HeadlessClient.create(endpoint));
47	    const guest = await track(HeadlessClient.join(endpoint, host.code.toLowerCase()));
48	    expect(guest.room.roomId).toBe(host.room.roomId);
49	    await host.waitFor(() => host.playerCount === 2);
50	
51	    const start = host.ship()!;
52	    expect(guest.ship(host.sessionId)).toEqual(start);
53	    const guestStart = guest.ship()!;
54	
55	    // Sail toward the middle of the sea, so the map edge cannot clamp the ship whatever its spawn slot.
56	    const direction = start.x < MAP_CENTRE_X ? 1 : -1;
57	    await host.hold({ moveX: direction, moveY: 0 }, 600);
58	    await host.waitFor(() => (host.ship()!.x - start.x) * direction > 0);
59	    const moved = host.ship()!;
60	    expect(moved.y).toBe(start.y);
61	
62	    // Both clients converge on the same server-decided position once the ship stops.
63	    await sleep(400);
64	    const settled = host.ship()!;
65	    await guest.waitFor(() => guest.ship(host.sessionId)?.x === settled.x);
66	    expect(guest.ship(host.sessionId)).toEqual(settled);
67	    expect((settled.x - start.x) * direction).toBeGreaterThan(0);
68	    // The guest sent nothing, so its ship has not moved.
69	    expect(guest.ship()).toEqual(guestStart);
70	    expect(host.ship(guest.sessionId)).toEqual(guestStart);
71	  });
72	
73	  it("removes a ship when its player leaves", async () => {
74	    const host = await track(HeadlessClient.create(endpoint));
75	    const guest = await HeadlessClient.join(endpoint, host.code);
76	    await host.waitFor(() => host.playerCount === 2);
77	    await guest.leave();
78	    await host.waitFor(() => host.playerCount === 1);
79	    expect(host.ship(guest.sessionId)).toBeUndefined();
80	  });
81	
82	  it("refuses a client with a different protocol version", async () => {
83	    await expect(HeadlessClient.create(endpoint, { protocolVersion: PROTOCOL_VERSION + 1 })).rejects.toThrow(
84	      /Protocol version mismatch/,
85	    );
86	    const host = await track(HeadlessClient.create(endpoint));
87	    await expect(HeadlessClient.join(endpoint, host.code, { protocolVersion: PROTOCOL_VERSION - 1 })).rejects.toThrow(
88	      /Protocol version mismatch/,
89	    );
90	    expect(host.playerCount).toBe(1);
91	  });
92	
93	  it("refuses an unknown code", async () => {
94	    await expect(HeadlessClient.join(endpoint, "ZZZZZ9")).rejects.toThrow(/No match with that code/);
95	  });
96	
97	  it("holds eight players and refuses a ninth", async () => {
98	    const host = await track(HeadlessClient.create(endpoint));
99	    for (let index = 0; index < 7; index++) await track(HeadlessClient.join(endpoint, host.code));
100	    await host.waitFor(() => host.playerCount === 8);
101	    const slots = new Set([...host.room.state.ships.values()].map((ship) => ship.slot));
102	    expect(slots.size).toBe(8);
103	    await expect(HeadlessClient.join(endpoint, host.code)).rejects.toThrow(/full/);
104	  });
105	});
